      "translation": "carino • grazioso",
      "explanation": [
        "Idea principale: hübsch è un aggettivo che significa «carino, grazioso»: si usa per l'aspetto delle persone, i vestiti, le case e le cose piacevoli da vedere. È più leggero di schön (bello).",
        "Davanti a un sostantivo hübsch si declina come un normale aggettivo: ein hübsches Kleid, eine hübsche Frau, hübsche Blumen. Comparativo: hübscher, superlativo: am hübschesten.",
        "Nella lingua parlata ganz hübsch può significare anche «parecchio, piuttosto»: Das war ganz hübsch teuer."
      ],
      "examples": [
        {
          "de": "Sie ist ein hübsches Mädchen.",
          "lv": "È una ragazza carina."
        },
        {
          "de": "Das Kleid ist wirklich hübsch.",
          "lv": "Il vestito è davvero carino."
        },
        {
          "de": "Was für ein hübsches Haus!",
          "lv": "Che casa carina!"
        },
        {
          "de": "Du siehst heute hübsch aus.",
          "lv": "Oggi sei proprio carina."
        }
      ],
      "comparison": [
        {
          "word": "schön",
          "meaning": "bello",
          "example": "Das Wetter ist schön. – Fa bel tempo."
        },
        {
          "word": "süß",
          "meaning": "tenero; dolce (di sapore)",
          "example": "Das Baby ist süß. – Il bebè è tenero."
        },
        {
          "word": "schick",
          "meaning": "elegante",
          "example": "Du siehst schick aus. – Sei elegante."
        }
      ],
      "tip": [
        "Hübsch si usa come complimento leggero, schön come complimento più forte.",
        "Aggiungi la desinenza quando la parola sta davanti a un sostantivo: ein hübsches Kleid, ma Das Kleid ist hübsch."
      ],
      "important": [
        "Per un uomo hübsch si usa più raramente; si dice piuttosto gut aussehend o attraktiv.",
        "Hübsch è molto usato nella lingua parlata, ma non è la stessa cosa di schön: schön è più generale e più forte."
      ],
