      "explanation": [
        "Idea principale: sich è il pronome riflessivo della 3ª persona e della forma di cortesia Sie: indica che l'azione ricade su chi la compie. All'accusativo e al dativo la forma è la stessa: sich.",
        "Le altre persone hanno forme diverse: ich – mich, du – dich, wir – uns, ihr – euch. Per esempio er wäscht sich (si lava), ma ich wasche mich (mi lavo).",
        "Molti verbi tedeschi sono riflessivi (sich freuen, sich setzen, sich vorstellen) e spesso corrispondono a verbi riflessivi italiani: rallegrarsi, sedersi, presentarsi."
      ],
      "examples": [
        {
          "de": "Er wäscht sich jeden Morgen.",
          "lv": "Si lava ogni mattina."
        },
        {
          "de": "Sie freut sich auf das Wochenende.",
          "lv": "Aspetta con gioia il fine settimana."
        },
        {
          "de": "Die Kinder setzen sich auf das Sofa.",
          "lv": "I bambini si siedono sul divano."
        },
        {
          "de": "Er kauft sich ein neues Handy.",
          "lv": "Si compra un cellulare nuovo."
        },
        {
          "de": "Sie stellt sich kurz vor.",
          "lv": "Si presenta brevemente."
        }
      ],
      "comparison": [
        {
          "word": "mich",
          "meaning": "mi / me stesso",
          "example": "Ich wasche mich. – Mi lavo."
        },
        {
          "word": "uns",
          "meaning": "ci / noi stessi",
          "example": "Wir freuen uns. – Siamo contenti."
        },
        {
          "word": "einander",
          "meaning": "l'un l'altro",
          "example": "Sie helfen einander. – Si aiutano l'un l'altro."
        }
      ],
      "tip": [
        "Anche con la forma di cortesia Sie si usa sich con la minuscola: Setzen Sie sich!",
        "Impara i verbi riflessivi insieme a sich: sich freuen, sich setzen."
      ],
      "important": [
        "Sich non si usa con ich, du, wir, ihr — lì servono mich, dich, uns, euch.",
        "Al plurale Sie sehen sich può significare sia “vedono sé stessi” sia “si vedono l'un l'altro”, come l'italiano “si vedono”; lo distingue il contesto."
      ],
